"Anyone remember why the sky is a portal?":"ვინმეს ახსოვს, რატომ არის ცა პორტალი?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"ამბობენ, თუ ლიფტის შახტაში გადახტები, მტრის შახტიდან ამოხვალ. არ გამოვცდი.",
"The Swarm painted their visors red again. Show-offs.":"figa-მ ისევ წითლად შეღება თვალები. ტრაბახები.",
