"Quiet. Too quiet.":"წყნარია. ზედმეტად წყნარი.",
"See that? Our base is above the Swarm base again. Portals, man.":"ხედავ? ჩვენი ბაზა ისევ figa-ს ბაზის თავზეა. პორტალები, ძმაო.",
"Diman, if you're reading this — we need a vacation.":"დიმან, თუ ამას კითხულობ — შვებულება გვჭირდება.",
