"Autosaved":"ავტომატურად შეინახა",
"robot war · the sky is a portal":"რობოტების ომი · ცა პორტალია",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"მოგესალმები მეტეორიტზე! შენ კონსორციუმის საბრძოლო რობოტი ხარ. მიიხედ-მოიხედე თაგუნათი და იარე WASD-ით.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"რეაქტიული ზურგჩანთა: შეეხე Shift-ს ახტომისთვის, დააჭირე და გეჭიროს ფრენისთვის. ენერგია მიწაზე ივსება.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"ცეცხლი — მარცხენა ღილაკი. დამიზნება — მარჯვენა ღილაკი: უფრო ზუსტია, ზუმით. ესროლე რამდენჯერმე.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"გადატენვა — R. ტყვიები ყველაზე მძლავრად საშუალო მანძილზე ურტყამს, 20–50 მეტრზე.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"რაკეტა — Q. ტანკებისა და შენობებისთვის. გაუშვი რაკეტა.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"ზემოთ სტრატეგის ბრძანებაა. გაირბინე მწვანე ისრებზე: მარშრუტზე სპრინტით მიდიხარ. წერტილის ხელში ჩასაგდებად — შუქურასთან დარჩი.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"შენი რაზმი გიფარავს: მათი პორტრეტები და ჯანმრთელობა მარცხნივაა. თუ ჩამორჩებიან, გთხოვენ დაელოდო.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — ერთეულის სწრაფი გადართვა ბრძოლის დატოვების გარეშე: გადახტი ბრძოლასთან ყველაზე ახლოს მყოფ რაზმში ან ტანკში. სცადე.",
"all":"ყველა",
"selected":"მონიშნული",
"Builders ({0}): mining crystals":"ინჟინრები ({0}): კრისტალების მოპოვება",
"Bosses unlock at 12:00 (time is skipped here). A factory is required — it is already built. Builder → \"Build\" → the boss plant → LMB at the marker.":"ბოსები 12:00-ზე იხსნება (დრო აქ გამოტოვებულია). საჭიროა ქარხანა — ის უკვე აშენებულია. ინჟინერი → „აშენება\" → ბოსის ქარხანა → მარცხენა ღილაკი მარკერზე.",
"The plant is going up. Then click it → order the boss (instant in the lesson; ~100 s in battle). One per army; the enemy gets a radio warning.":"ქარხანა შენდება. შემდეგ დააჭირე მას → შეუკვეთე ბოსი (გაკვეთილზე მყისიერია; ბრძოლაში ~100 წ). თითო არმიაზე ერთი; მტერს რადიოთი გაფრთხილება მიუვა.",
"Huge hull (bar at the top), very slow, slow to turn. Select it (LMB) and RMB on the \"HERE\" marker.":"უზარმაზარი კორპუსი (ზოლი ზემოთ), ძალიან ნელია და ნელა ტრიალებს. მონიშნე (მარცხენა ღილაკი) და მარჯვენა ღილაკი მარკერზე „აქ\".",
"Possess your boss: select it in strategy and press {0} (or \"▶ Possess\"). Outside camera, LMB — main weapon.":"დაეუფლე შენს ბოსს: სტრატეგიაში მონიშნე და დააჭირე {0}-ს (ან „▶ ფლობა\"). კამერის გარეთ მარცხენა ღილაკი — ძირითადი იარაღი.",
"Bosses unlock at 12:00 (skipped here). Builder → \"Build\" → the boss plant → tap the marker → \"Build\".":"ბოსები 12:00-ზე იხსნება (აქ გამოტოვებულია). ინჟინერი → „აშენება\" → ბოსის ქარხანა → შეეხე მარკერს → „აშენება\".",
"The plant is going up. Then tap it → order the boss (instant here). One per army.":"ქარხანა შენდება. შემდეგ შეეხე მას → შეუკვეთე ბოსი (აქ მყისიერია). თითო არმიაზე ერთი.",
"Huge hull, very slow. Tap it, then tap the \"HERE\" marker.":"უზარმაზარი კორპუსი, ძალიან ნელია. შეეხე მას, შემდეგ შეეხე მარკერს „აქ\".",
