"Capture and hold points — each pays income and opens its vein.":"დაიკავე და დაიჭირე წერტილები — თითოეული შემოსავალს იძლევა და თავის ძარღვს ხსნის.",
"Research \"Deep drilling\" at the HQ: +35% extractor output per level.":"შტაბში შეისწავლე \"ღრმა ბურღვა\": +35% ექსტრაქტორებს თითო დონეზე.",
"Protect builders and extractors: the Swarm hunts them. A turret next to a vein pays off.":"დაიცავი ინჟინრები და ექსტრაქტორები: ნახიდი მათზე ნადირობს. ძარღვის გვერდით კოშკურა ანაზღაურდება.",
