"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"ახლა სტრატეგია. შეეხე «◩ სტრატეგიას» მარჯვენა ზედა კუთხეში — ბრძოლის ველი ზემოდან.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"ახლა სტრატეგია. დააჭირე {0}-ს (ან «◩ სტრატეგიას» მარცხენა ზედა კუთხეში) — ბრძოლის ველი ზემოდან.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"სტრატეგიაში გზამკვლევი გეხმარება: ზედა ფანჯარა გეუბნება რა გააკეთო, ჩარჩო ღილაკს აჩვენებს, რგოლი — ადგილს რუკაზე. შეასრულე მისი სამი რჩევა.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"მონიშნე რაზმი და დააჭირე მწვანე ღილაკს «▶ ფლობა» — ისევ ბრძოლაში ამ ჯარისკაცით. სანამ ისვრი, AI სტრატეგი თავად მართავს არმიას.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"მონიშნე რაზმი და დააჭირე {0}-ს ან მწვანე «▶ ფლობას» — ისევ ბრძოლაში ამ ჯარისკაცით (მონიშვნის გარეშე — შენით). სანამ ისვრი, AI სტრატეგი თავად მართავს არმიას.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"წვრთნა დასრულდა! ნახიდი იწყებს შეტევას. წარმატებები, ჯარისკაცო!",
