"Build ▸":"შენობები ▸",
"Then click (tap) the ground: they move, stop to fight enemies they meet, then continue. On an enemy — attack it. Same as RMB.":"მერე დააკლიკე (შეეხე) მიწას: მიდიან, მტერს რომ შეხვდებიან, გაჩერდებიან და იბრძვიან, მერე გზას აგრძელებენ. მტერზე — შეუტიე. იგივეა, რაც მარჯვენა ღილაკი.",
