"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"ყუმბარა: დაიჭირე G — დაინახავ რკალს და აფეთქების წრეს; გადაუსვი თითი ღილაკზე — კუთხე; გაუშვი — ესროლე.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"ყუმბარა: დაიჭირე {0} — რკალი და აფეთქების წრე, გაუშვი — ესროლე. მანძილი — ხედვის კუთხით, ბორბალი — ძალა, მარჯვენა ღილაკი — ფეხქვეშ.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"ყუმბარები: დაიჭირე G — ფრენის რკალი, აფეთქების წერტილი და წრე, დისტანცია; გაუშვი — ესროლე. მანძილი — ხედვის კუთხით, ბორბალი — ძალა, მარჯვენა ღილაკი — ფეხქვეშ",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"ყუმბარა ხტება და ფერდობზე გორავს, აფეთქება 2.5 წმ-ში; 2 ყუმბარა, აღდგენა 9 წმ; გამაფრთხილებელი ხატულა ახლომდებარე მტრის ყუმბარაზე",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"ყუმბარა: დაჭერა — რკალი და აფეთქების წერტილი, გაშვება — სროლა · ტანკის ფორსაჟი",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — დაიჭირე: ჩანს რკალი და აფეთქების წრე, გაუშვი — ესროლე. აფეთქება 2.5 წმ-ში, 2 ყუმბარა.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"ყუმბარა ({0}): დაიჭირე — ფრენის რკალი, აფეთქების წერტილი და წრე, დისტანცია; გაუშვი — ესროლე; მოკლე დაჭერა — მაშინვე ესროლე. მანძილი — ხედვის კუთხით, ბორბალი — ძალა, მარჯვენა მაუსის ღილაკი — ქვემოდან. ტელეფონი: დაიჭირე G და გადაუსვი თითი.",
