"HQ: train a builder":"შტაბი: ინჟინრის დაკვეთა",
"Build keys (Z X C V B N K) pick the nearest builder automatically.":"მშენებლობის კლავიშები (Z X C V B N K) უახლოეს ინჟინერს თავისით ირჩევს.",
