"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"კაფსულა წერტილზე {0}: {1}{2}{3}. ინჟინერს შეუძლია ავანპოსტის დადგმა (V) და გაუმჯობესების ტოტის არჩევა.",
