" · AI drives vehicles, E next to one — man its gun":" · ტექნიკას ხელოვნური ინტელექტი მართავს, E ტექნიკასთან — დაჯექი ქვემეხთან",
"Possess squads (infantry)":"რაზმების (ქვეითი ჯარის) კონტროლი",
"Possess vehicles and drones":"ტექნიკის და დრონების კონტროლი",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"ქვემეხთან: {0}. მანქანას AI მართავს, შენ ისვრი. {1} — ჩამოსვლა",
