"Voice of hints and curator":"მინიშნებებისა და გზამკვლევის ხმა",
"Advanced: custom class order":"გაფართოებული: კლასების საკუთარი რიგი",
"Voice of hints & curator":"მინიშნებებისა და გზამკვლევის ხმა",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"ტელეფონი: ჯოისტიკის სამი რეჟიმი. მხოლოდ მარცხენა — „ავტო“ (ძლიერი მაგნიტი, სუსტი ტყვიები). მხოლოდ მარჯვენა — მიზანი თავისით ირთვება, მაგნიტი უფრო ძლიერია, სროლა უფრო ზუსტი. ორივე ერთად — მიზნის გარეშე, მაგნიტი და სიზუსტე უფრო სუსტია. ღილაკი 👁 მარჯვნივ — ინტერფეისის დამალვა/დაბრუნება.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"ტელეფონი: სტრატეგია გამარტივებულია — მხოლოდ ინჟინერი და შენობები. მარცხნივ ბარათებია (ინჟინერი, შტაბი, ყაზარმა…): შეხება — კამერა იქ გადაადგილდება, ქვემოთ ჩანს რა ავაშენოთ/აწარმოოთ. „ბრძოლაში“ — მარცხნივ ზემოთ. არმია თავად იბრძვის. სრული სტრატეგია — პარამეტრები → ტელეფონი.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"ფლობა — ორი გადამრთველი: „რაზმები“ და „ტექნიკა“ (ტელეფონზე ტექნიკა ნაგულისხმევად გამორთულია — მას AI მართავს). თუ ტექნიკა გამორთულია, E (ტელეფონზე — ღილაკი მარჯვნივ) მეგობრულ მანქანასთან — დაჯექი მის ქვემეხთან: მანქანა თავად მიდის, შენ ისვრი. ძველი „კლასების საკუთარი რიგი“ — „გაფართოებულში“. ფლობისას ერთეული რადიოთი გიპასუხებს.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"ჭკვიანი მინიშნებები: ძირითადი მინიშნებები მე-2 გაშვების შემდეგ თავად ქრება, მაგრამ თამაში მაინც გაგახსენებს ფუნქციას, რომელსაც არასდროს იყენებ. გადამრთველები: ძირითადი / გაფართოებული / იშვიათი, ცალკე — მინიშნებებისა და გზამკვლევის ხმა.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"თანაგუნდელები ჩამორჩნენ ან დაიღუპნენ — სტრატეგი ახლებს გიგზავნის კაფსულით (ჩვეულებრივ შევსებაზე ძვირი). v7.2gfx გრაფიკა და ხმა შემოვიდა: ღრუბლებად ასული აფეთქებები, კვამლი, ნამსხვრევები, შახტებისა და კრატერების აკუსტიკა. აწყობის თარიღი ახლა რეალურია.",
