"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"კარიერა და შენახვები არ იცვლება. ბრძოლაში იგივე მენიუ არის ღილაკი „🛠 მენიუ“ მარჯვნივ ზემოთ{0}.",
"New developer match":"დეველოპერის ახალი მატჩი",
"all unlocked, endless ore, instant build, arsenal":"ყველაფერი ღიაა, უსასრულო მადანი, მყისიერი მშენებლობა, არსენალი",
"Trainings — all 4":"წვრთნები — ოთხივე",
"PC and phone (strategy and shooter)":"კომპიუტერი და ტელეფონი (სტრატეგია და მსროლელი)",
"Cinema: split screen":"კინო: გაყოფილი ეკრანი",
"strategist bot left, shooter bot right":"მარცხნივ ბოტი-სტრატეგი, მარჯვნივ ბოტი-მსროლელი",
"Cinema: everything built":"კინო: ყველაფერი აშენებულია",
"both bases built and upgraded — for footage":"ორივე ბაზა აშენებული და გაუმჯობესებულია — გადასაღებად",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"კინო-რეჟიმი — გაყოფილი ეკრანი: მარცხნივ ბოტი-სტრატეგი (ხედი ზემოდან ბაზასა და არმიაზე), მარჯვნივ ბოტი-მსროლელი პირველი პირიდან. ღილაკები ქვემოთ (და კლავიშები S, P): „გაყოფილი ეკრანი“ და „★ ყველაფერი აშენებულია“ — ორივე ბაზა აშენებული და გაუმჯობესებულია გადასაღებად.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"ბირთვი და მეტეორიტის გამჭოლი გვირაბები აღარ არსებობს — მეტეორიტი მყარია, ბრძოლა მხოლოდ ზედაპირზე მიმდინარეობს.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"ტელეფონი: 👁 მალავს ინტერფეისს, მაგრამ ტოვებს რეაქტიულ ზურგჩანთას, ⇆-ს, სტიკებს და ამოცანის მარკერს. «◎ დამიზნება» (მხოლოდ მარჯვენა თითი) — შესამჩნევად ძლიერი და ფართო მაგნიტი; სამივე რეჟიმის მაგნიტის სიძლიერე — პარამეტრები → მართვა → «გაფართოებული». მანქანის ქვემეხთან ღილაკს ჰქვია «ჩამოსვლა».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"წვრთნა: ტელეფონზე — მხოლოდ სატელეფონო, კომპიუტერზე — მხოლოდ კომპიუტერის. ოთხივე — მენიუში «🛠 დეველოპერი». დეველოპერის რეჟიმი და არსენალი ერთ მენიუშია გაერთიანებული (ბრძოლაში — «🛠 მენიუ» ზევით მარჯვნივ, კომპიუტერზე კიდევ F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"გრაფიკის სტილები «Dendy (8-ბიტიანი)» და «16-ბიტიანი»: პარამეტრები → გრაფიკა → «გრაფიკის სტილი» (დეტალები — ⚙ ღილაკი). თუ მატჩის პირველ ~10 წმ-ში FPS 24-ზე დაბალია, Dendy თავისით ირთვა (20-ზე დაბლა — უფრო მსხვილი პიქსელი, 120 ხაზი); ზედა ზოლი «ჩვეულებრივზე დაბრუნება» ჩვეულებრივ გრაფიკას სამუდამოდ აბრუნებს. შენი არჩევანი მენიუში ყოველთვის უპირატესია.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"გარემოს 3D მოდელები (ნანგრევები, ტექნიკა, გამაგრებები) — მხოლოდ კარგად შეფასებულები; იტვირთება მოთხოვნისას ინტერნეტიდან. გამორთვა: პარამეტრები → გრაფიკა → «გარემოს ახალი 3D მოდელები».",
"New in v7.5":"სიახლეები v7.5-ში",
"NEW IN v7.5":"სიახლეები v7.5-ში",
