"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"სტრატეგი: ⌖ ნიშანი მტრის თავყრილობაზე, {0} მ — საარტილერიო დარტყმა 8 წამში. არ მიუახლოვდე!",
"MLRS \"Grad\" ×{0}: salvo at the strategist's mark":"რეაქტიული ცეცხლის სისტემა «გრადი» ×{0}: ზალპი სტრატეგის ნიშანზე",
"a heavy MG for 90 s":"მძიმე ტყვიამფრქვევი 90 წმ-ით",
"incendiary rounds for 60 s":"ცეცხლგამჩენი ვაზნები 60 წმ-ით",
