"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"მშენებლობა ჯარისკაცებით: E (ტელეფონზე «შესვლა») საკუთარ მშენებლობასთან — ჯარისკაცი თავად აშენებს, ახლომდებარე თანაგუნდელები ეხმარებიან. თუ ინჟინრები დაკავებულები არიან, სტრატეგი თავად მოგთხოვს დახმარებას — ნიშანი «მშენებლობა».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"სტრატეგის ნიშნები: სტრატეგი ⌖-ს სვამს შენს ახლოს მტრის თავყრილობაზე — 8 წმ-ის შემდეგ იქ არტილერია ურტყამს, ახლომდებარე საკუთარი რეაქტიული სისტემები «გრადი» კი ზალპს იძლევიან. შენი საარტილერიო დარტყმა სტრატეგიის რეჟიმიდან «გრადების» მხარდაჭერასაც იღებს.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"იარაღის საცავები სატვირთო კონტეინერებსა და ჩამოვარდნილ თანამგზავრებში (📦 ჩანს 70 მ-დან): E — ტყვიამფრქვევი 90 წმ-ით, ცეცხლგამჩენი ვაზნები ან რაკეტები, პლუს სავსე ყუმბარები. ხოხვა: Ctrl — ჩაწოლა / ადგომა (უფრო დაბლა, უფრო ზუსტად, მაგრამ ნელა).",
