"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ ითამაშე ახლავე» — მენიუს პირველი ღილაკი: მოკლე გადაფრენა პორტალ-ცის ქვეშ — და პირდაპირ ბრძოლაში (გამოტოვება — ნებისმიერი ღილაკი ან შეხება).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"დარტყმები იგრძნობა: მეტალის ხმა და ნაპერწკლები, მკვლელობის ნიშანი სამიზნესთან (თავში — ყვითელი), სერია ×N, აფეთქებებისგან რბილი ქანაობა, სლოუ-მო მნიშვნელოვან მკვლელობებზე. ქანაობა, სლოუ-მო და მინიშნება პარამეტრებში გამოირთვება.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"მატჩის შედეგი: დრო, განადგურებულები, საუკეთესო სერია, ★ MVP და საუკეთესო რაზმი, მატჩის ბარათი — «⇪ გაზიარება», PNG ან ბმული თამაშზე.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"მინიშნება «რა გავაკეთო ახლა» მარცხნივ რესურსების ქვეშ: სტრატეგის ბრძანება, ხელში ჩასაგდები წერტილი, ჯგუფის (ნახლის) იერიში. ✕ ან F7 — ჩაკეცვა.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"ბრძოლა თავისით ინახება, თუ ჩანართს დახურავ ან ჩაკეცავ — მენიუში «⟲ გაგრძელება».",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 რჩება მენიუში «🕘 თამაშის ვერსია» — თუ ახალი არ მოგეწონა. ანონიმური სტატისტიკა (სახელებისა და ფოსტის გარეშე) ახლა იგზავნება; გამორთვა — პარამეტრებში.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«ითამაშე ახლავე», დარტყმების უკუკავშირი, მატჩის შედეგი ბარათით, მინიშნება «რა გავაკეთო», ავტოშენახვა",
"and older: v7.5, v7.4, milestones v1–v7.0":"და ძველი: v7.5, v7.4, ეტაპები v1–v7.0",
"New in v7.6":"სიახლეები v7.6-ში",
"NEW IN v7.6":"სიახლეები v7.6-ში",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"ფრაქციის არჩევა მატჩამდე: «კონსორციუმი» (მძიმე ქვეითი ძალოვან ჯავშანში, ჯავშანი და არტილერია) ან «ნახლი» (სიჩქარე, დრონების გუნდები, მძიმე გასროლები დამახინჯებით). AI მეორეს თამაშობს. არჩევანი დამახსოვრდება.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"ყველა ფრაქციას საკუთარი ტექნიკა და უნიკალური აქვს: კონსორციუმს — ტანკი «რინოცეროსი» და «კერამიტის ფილები», ნახლს — «დრონების გუნდი» და «ფაზური ზურგჩანთები». ბალანსი ბოტების მატჩებით შემოწმებულია.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"აფეთქების ხვრელები: არტილერია, რაკეტები და ტანკების ქვემეხები მეტეორიტში ორმოებს თხრიან — მათში გაივლი და გაიარებ ტექნიკით, ასევე შეგიძლია შიგ შეეფარო.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"მესამე პირის ხედი ჯარისკაცისთვის (V, ახსოვს არჩევანს; ტელეფონზე — მართვა) და ტექნიკის რბილი კამერა ნიშნით, სად მოხვდება ქვემეხი.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 დარჩა მენიუში „🕘 თამაშის ვერსია“ — თუ ახალი არ მოგეწონება.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"კონსორციუმის / ნახლის ფრაქციები მატჩის წინ არჩევანით, აფეთქების ხვრელები, მესამე პირის ხედი",
