"Anomaly! The ground shimmers with heat — a Brazier!":"ანომალია! მიწა სიცხისგან თრთის — საკურთხეველია!",
"Careful, a Brazier underfoot!":"ფრთხილად, ფეხქვეშ საკურთხეველია!",
"Anomaly — green mist! Acid, hold your breath!":"ანომალია — მწვანე ნისლი! მჟავაა, სუნთქვას ვიკავებთ!",
"The mist is drifting our way, go around!":"ნისლი ჩვენკენ მოდის, შემოვუაროთ!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"ანომალია! ჰაერი შუშასავითაა — ლინზაა, ტყვიებს ზნექს!",
"Everything is warping… a Lens nearby!":"სურათი იღუნება… ლინზა ახლოსაა!",
"Ha! An enemy walked right into the anomaly!":"ჰა! მტერი პირდაპირ ანომალიაში შევიდა!",
"Got him! Lure them into anomalies!":"მოვარდა! შეიტყუე ისინი ანომალიებში!",
"Beautiful zap! One less tin can.":"ლამაზად გაიჭედა! ერთით ნაკლები რკინა.",
"The anomaly got me!":"ანომალიამ მომიტანა!",
"Ow! Don't go in there!":"აი! იქ ნუ შედიხართ!",
"Discharged! It is dormant now.":"განვმუხტე! ახლა სძინავს.",
"Clear, the anomaly is discharged.":"სუფთაა, ანომალია განმუხტულია.",
"They say veins hide artifacts. Only first the vein sings…":"ამბობენ, ძარღვებში არტეფაქტებს მალავენო. ოღონდ ჯერ ძარღვი გალობს…",
"Throw a bolt first, then walk. Old habit.":"ჯერ ბოლტი ესროლე, მერე იარე. ძველი ჩვეულებაა.",
