" — close":" — დახურვა",
"Supply drop":"მარაგის ყუთი",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"თქვენი ძალების გვერდით ყუთს ყრის: ვაზნები, ყუმბარები, რაკეტები, იარაღის ნაწილები, სარემონტო ნაკრები.",
"\"Grad\" rocket strike":"„გრადის“ დარტყმა",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 რაკეტა დიდ ფართობზე 3 წამში — საარტილერიო დარტყმაზე სწრაფი და ფართო.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"მხარდაჭერა: ყუთი, დაზვერვა, „გრადი“, საარტილერიო დარტყმა (მერე 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"ყურადღება: ნახლის „გრადი“ თქვენს რაიონზე!",
"Warning! Rocket salvo on our position!":"ყურადღება! რეაქტიული ზალპი ჩვენს პოზიციაზე!",
"take the supply crate":"მარაგის ყუთის აღება",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"ანომალიები მეტეორიტზე (ტალღა 1): „სიმღერის ძარღვი“ — მანათობელი მწვანე კრისტალი, გუგუნებს და რიტმული იმპულსებით ურტყამს ყველას ახლოს; „ანგარა“ ითრევს და ისვრის, „მტკაცუნა“ ელვებს ისვრის ლურსმნებს შორის, „საკურთხეველი“ ფეხქვეშ აინთება, „მჟავა ნისლი“ და „ლინზა“ (ტყვიებსა და სურათს ზნექს) დაცურავენ.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"ანომალიები წინასწარ იგრძნობა (გუგუნი, ბზინვა, ცხელი ჰაერი). განმუხტე — ყუმბარით, რაკეტით ან ბოლტით (E ანომალიასთან): დაიძინებს, ზოგჯერ არტეფაქტს დატოვებს პლიუსითა და მინუსით. რაზმი რაციით გაფრთხილებს, მტრები (და თავისიანებიც) ზოგჯერ თვითონ შედიან მათში — შეიტყუე!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"მხარდაჭერა სარდლობის ქულებით: ბრძოლაში 4 (ტელეფონზე 📡) — მარაგის ყუთი, დაზვერვა, „გრადის“ დარტყმა, საარტილერიო დარტყმა სამიზნეზე. სტრატეგი რუკაზე ანომალიებს მხოლოდ დაზვერვის შემდეგ ხედავს.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"მარაგის ყუთები ძველი ექსპედიციების ნანგრევებში, შტაბებთან და აშენებული შენობების გვერდით: ვაზნები, ყუმბარები, რაკეტები, იარაღის ნაწილები (ხსნიან დამატებებს).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 დარჩა მენიუში „🕘 თამაშის ვერსია“. ანომალიების გამორთვა პარამეტრებშია.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"ანომალიები („მგალობელი ძარღვი“ და კიდევ 5), განმუხტვა ბოლტითა და ყუმბარით, არტეფაქტები, მხარდაჭერა სარდლობის ქულებით, მარაგის ყუთები",
"and older: v7.7, v7.6, milestones v1–v7.0":"და ძველი ვერსიები: v7.7, v7.6, ეტაპები v1–v7.0",
