"NEW IN v7.8":"სიახლე v7.8-ში",
"Close":"დახურვა",
"Anomalies on the meteor":"ანომალიები მეტეორიტზე",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ კუთხეში — პაუზის მენიუ: „გაგრძელება“, „თავიდან დაწყება“, „წვრთნა“, „გრაფიკა“, „პარამეტრები“, „მთავარი მენიუ“ (დადასტურებით). ტელეფონი: ☰ ზემოთ მარჯვნივ (ბრძოლის მოქმედებები — ფილა „⚡ მოქმედებები“); კომპიუტერი: ღილაკი „☰ მენიუ“ ზემოთ მარჯვნივ ან Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"გრაფიკა ნაგულისხმევად ყოველთვის ჩვეულებრივია — Dendy მხოლოდ შენი არჩევით: გადამრთველი „გრაფიკა: ჩვეულებრივი / Dendy (8-ბიტი) / 16-ბიტი“ პირდაპირ მთავარ მენიუსა და პაუზაშია. თუ თამაში ძალიან ანელებს — გამოჩნდება მინიშნება ღილაკით „Dendy-ს ჩართვა“.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"ტელეფონი და პლანშეტი: მოქმედების ღილაკი „✋“ მარჯვნივ მხოლოდ მაშინ ჩნდება, როცა ახლოს რაღაცის გაკეთება შეიძლება — „აღება“ (საცავი, ყუთი), „ჯდომა“ (ტექნიკა, კოშკურა, ქვემეხი), „აშენება“, „ჩამოსვლა“, „ბოლტი“ ანომალიასთან. შეგიძლია უბრალოდ შეეხო გაშუქებულ ობიექტსაც.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"ტელეფონი, სტრატეგია: დააჭირე თითი ~0,3 წმ (ტელეფონი აგიკანკალდება, გამოჩნდება ყვითელი რგოლი) და გაატარე — არჩევის ჩარჩო; ჩვეულებრივი გადაფურცვლა — კამერა. მარჯვნივ არის ღილაკი „ჩარჩო“; წვრთნაში ნაბიჯი „ჩარჩო“ რაზმზე შეხებასაც ითვლის.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"ტელეფონი: პატარა ღილაკებზე დაჭერა გაადვილდა, მხარდაჭერის სია 📡 უფრო დიდია, სტრატეგიის პანელები აღარ ფარავს პაუზასა და შედეგებს. v7.8 დარჩა მენიუში „🕘 თამაშის ვერსია“.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"მენიუ ☰ ტელეფონსა და კომპიუტერზე, გრაფიკა ავტო-Dendy-ს გარეშე, ღილაკი „✋“ ტელეფონზე, არჩევის ჩარჩო ტელეფონზე",
"16-bit":"16-ბიტი",
"Lagging? Try the Dendy graphics — they are lighter.":"ანელებს? ჩართე Dendy-გრაფიკა — უფრო მსუბუქია.",
