"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"დააჭირე თითი მიწას ~0,3 წმ — ტელეფონი აგიკანკალდება და გამოჩნდება ყვითელი რგოლი — და თითის აუღებლად გაატარე: მიიღება ჩარჩო. ან ღილაკი „ჩარჩო“ მარჯვნივ. შეგიძლია უბრალოდ რაზმზეც შეეხო.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhone-ზე სრული ეკრანისთვის: „გაზიარება“ ⬆ → „საწყის ეკრანზე დამატება“ — თამაში Safari-ს პანელების გარეშე გაიხსნება.",
"Open portal-meteor.pages.dev for that.":"ამისთვის გახსენი საიტი portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"შეხება — არჩევა · შეხება მიწაზე — სვლა · ხანგრძლივი შეხება — ბრძანებების მენიუ · ხანგრძლივი შეხება და გაყოლა — ჩარჩო · 2 თითი — მასშტაბი",
"Robo-ninja":"რობო-ნინძა",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"გმირი-მკვლელი: რუშ-ტელეპორტები, კატანა, სიურიკენები. თავისით ხტება მტრის ზონებში და რობოტებს ჭრის. თითო მხარეზე 1.",
"Shadow protocol":"პროტოკოლი „აჩრდილი“",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"კვლევა: ყაზარმაში რობო-ნინძას ხსნის. საჭიროა აშენებული მექების ქარხანა.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"გმირი (1 თითო მხარეზე): თავისით ტელეპორტირდება მტრის ზონებში და რობოტებს ჭრის; გააკონტროლე და ხელით ითამაშე.",
"is ready. She works on her own (AUTO) — possess her to play manually":"მზადაა. თავისით მუშაობს (ავტო) — გააკონტროლე, რომ ხელით ითამაშო",
"Robo-ninja ready for action":"რობო-ნინძა ბრძოლისთვის მზადაა",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ დაზვერვა: მტერს რობო-ნინძა გაუჩნდა!",
"Warning! The enemy has a robo-ninja. Stay together":"ყურადღება! მტერს რობო-ნინძა ჰყავს. ერთად დარჩით",
"cyber blinks":"კიბერ-რუშები",
"Too far for a dash — get closer or teleport":"რუშისთვის შორსაა — მიუახლოვდი ან ტელეპორტი",
"point ":"წერტილი ",
"enemy group":"მტრის ჯგუფი",
"order":"ბრძანება",
"nearby":"ახლოს",
"Zone cleared":"ზონა გაწმენდილია",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ ნინძების დუელი! დარტყმის წინ ბლოკი — პარირება, რუში — თავის არიდება. უყურე მოქნევის ანთებას",
"The two ninjas have met in a duel!":"ორი ნინძა დუელში შეეჯახა!",
"⚔ Duel won! Our ninja prevails":"⚔ დუელი მოგებულია! ჩვენი ნინძა უფრო ძლიერია",
"⚔ Duel lost…":"⚔ დუელი წაგებულია…",
"ninja duel":"ნინძების დუელი",
"POSTURE BROKEN":"პოზა დაირღვა",
"Teleport":"ტელეპორტი",
"Teleport: aim at the ground (up to 150 m)":"ტელეპორტი: სამიზნე მიწაზე დაუმიზნე (150 მ-მდე)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ ავტო: თავისით ხტება მტრის ზონებში და ჭრის. ჯოისტიკი / WASD — პაუზა 1.5 წმ-ით",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ ხელით: შეხება მტერზე — რუში და დარტყმა, გადაფურცვლა — მოქნევა, 🛡 — ბლოკი",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ ხელით მართვა: მარცხენა ღილაკი — კატანა, მარჯვენა ღილაკი — ბლოკი, Shift — რუში, Q — სიურიკენები, G — ტელეპორტი",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ ნინძა: შეხება მტერზე — ნახტომი და დარტყმა, გადაფურცვლა მარჯვნივ — მოქნევა, ● — დარტყმა, 🛡 — ბლოკი (დროულად = პარირება), ⇑ — ნახტომი, ✦ — შურიკენები, ◎ — ტელეპორტი, AUTO — თავად",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ ნინძა: მარცხენა ღილაკი — კატანა (დაჭერა — მძიმე დარტყმა), მარჯვენა ღილაკი — ბლოკი (დროულად = პარირება), Shift/Z — ნახტომი, Q — შურიკენები, G — ტელეპორტი სამიზნისკენ, ნახტომი ჰაერში — ორმაგი ნახტომი / კედელზე სირბილი, {0} — AUTO",
"Robo-ninja: AUTO on/off":"რობო-ნინძა: AUTO ჩართ./გამორთ.",
