"Radio Portal Meteor (EDMITRY): volume":"რადიო Portal Meteor (EDMITRY): ხმა",
"Radio: start by itself in battle":"რადიო: ბრძოლაში თავისით ჩართვა",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"რობო-ნინძა: კიბორგი კატანით. იხსნება ყაზარმაში კვლევით „პროტოკოლი ‘ჩრდილი’“ (საჭიროა მექანიკური ქარხანა). თავად ტელეპორტირდება მტრის ზონებში, ჭრის მტრებს ნაწილებად (სისხლის გარეშე — ნაპერწკლები), ნახტომები, შურიკენები, დუელები მტრის ნინძასთან. გამოიყენე „შეტევა“ — AUTO რეჟიმი ან ხელით მართვა (ტელეფონზე — საკუთარი ღილაკები).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"რადიო Portal Meteor: EDMITRY-ს 103 ტრეკი პირდაპირ თამაშში. ღილაკი 5 (გადანიშვნადია), ტელეფონზე — ☰ → პარამეტრები → ხმა. ხმა და „ბრძოლაში თავისით ჩართვა“ პარამეტრებშია; მუსიკა ჩუმდება აფეთქებებზე და რაციის ხმაზე.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"ახალი ენები: უზბეკური და ტაჯიკური — სრულად; ჩინური, ესპანური, პორტუგალიური — ნაწილობრივ. ენის ახალი არჩევანი მენიუში „ახალი მატჩის“ გვერდით.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"ტელეფონი: „ხატულების დამალვა“ 👁 დარჩენილ ღილაკებს მოწესრიგებულ სვეტად აგროვებს მარჯვენა კიდესთან; პორტრეტი აღარ ეხება ერთმანეთს; iPhone — თამაში აღარ ეწინააღმდეგება Safari-ს ჟესტებს, ხოლო „გაზიარება → საწყის ეკრანზე დამატება“ მას სრულ ეკრანზე უშვებს.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1-დან: ☰ მენიუ კუთხეში (პაუზა, თავიდან, წვრთნა, გრაფიკა), ავტო-Dendy-ს გარეშე, ✋ მოქმედების ღილაკი ტელეფონზე. v7.8.1 და v7.8 დარჩა მენიუში „🕘 თამაშის ვერსია“.",
