"Squad {0} is lost — its veterancy (lv {1}) is gone. See \"My squads → Fallen\".":"რაზმი {0} დაიღუპა — ვეტერანობა (დონე {1}) დაკარგულია. იხილე «ჩემი რაზმები → დაღუპულები».",
