"MY SQUADS":"ᲩᲔᲛᲘ ᲠᲐᲖᲛᲔᲑᲘ",
"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"ვეტერანობა ბრძოლებს შორის ინახება. რაზმი აგროვებს გამოცდილებას (ქვეითი 1, შენობა 2, ტექნიკა 3), იღებს დონეებს, ვარსკვლავებსა და პერკებს. ახალ ბრძოლაში ვეტერანები პირველები გამოდიან ასპარეზზე. დაღუპული რაზმი ყველაფერს კარგავს და «დაღუპულებში» ხვდება.",
"Active":"აქტიური",
