"Smoke grenades":"ბოლქვიანი ყუმბარები",
"A screen at a point for 14 s — enemies cannot see through.":"ფარდა წერტილში 14 წმ-ით — მტრები მასში ვერ ხედავენ.",
"Flank sprint":"ფლანგური რბენა",
"Run to a point at ×1.6 speed without stopping to fight (7 s).":"სირბილით წერტილისკენ ×1.6 სიჩქარით, ბრძოლაში ჩაბმის გარეშე (7 წმ).",
"Suppressing fire":"ჩახშობის ცეცხლი",
"Saturating fire on a 14 m area: enemies slowed and missing (7 s).":"ცეცხლის ქარიშხალი 14 მ ფართობზე: მტრები შენელებულნი არიან და აცდენენ (7 წმ).",
"Field medic":"საველე მედიკოსი",
"+20% hull to all at once, then 4 s of repair.":"ყველას მაშინვე +20% კორპუსი, შემდეგ კიდევ 4 წმ რემონტი.",
"Regen burst":"რეგენერაციის აფეთქება",
"Swarm: 8 s of fast regeneration for the whole squad.":"რაზმი: მთელი რაზმის სწრაფი რეგენერაცია 8 წმ-ით.",
"Grenade volley":"ყუმბარების ზალპი",
"Every trooper throws a grenade at the point.":"ყოველი ჯარისკაცი ყუმბარას ისვრის წერტილში.",
"AT rocket":"ტანკსაწინააღმდეგო რაკეტა",
"Heavy rockets at a vehicle or building (up to 3).":"მძიმე რაკეტები ტექნიკასა თუ შენობაზე (3-მდე).",
"Mini barrier":"მინი-ბარიერი",
"Consortium: a concrete section in front of the squad for 40 s.":"კონსორციუმი: ბეტონის სექცია რაზმის წინ 40 წმ-ით.",
"No squads to command — order a squad":"სამართავი რაზმები არ არის — შეუკვეთე რაზმი",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"მეთაური: {0}. მარცხენა ღილაკი — სვლა / შეტევა, 1–4 — უნარები, Tab — სხვა რაზმი, ორმაგი დაწკაპუნება ჯარისკაცზე — ბრძოლა, P — სტრატეგია",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"შეხება — სვლა/შეტევა, ორმაგი შეხება ჯარისკაცზე — ბრძოლა, მარჯვენა ღილაკები — უნარები",
