"COMMANDER":"მეთაური",
"Fight: possess a trooper of the squad":"ბრძოლაში: რაზმის ჯარისკაცის დაუფლება",
"Fight":"ბრძოლაში",
"Tap a point on the map (or the same button to cancel)":"შეეხე წერტილს რუკაზე (ან იმავე ღილაკს — გაუქმება)",
"LMB — where to use · same key — at cursor · RMB / Esc — cancel":"მარცხენა ღილაკი — სად გამოვიყენოთ · იგივე კლავიში — კურსორზე · მარჯვენა ღილაკი / Esc — გაუქმება",
"Tap — move / attack · double-tap a trooper — fight · drag — rotate, pinch — zoom":"შეხება — სვლა / შეტევა · ორმაგი შეხება ჯარისკაცზე — ბრძოლა · გადაწევა — ბრუნვა, მოჭიმვა — მასშტაბი",
"LMB — move / attack (2× run) · double-click a trooper — fight · Tab — squad · Q/E, wheel — camera · H — hold":"მარცხენა ღილაკი — სვლა / შეტევა (2× — სირბილით) · ორმაგი დაწკაპუნება ჯარისკაცზე — ბრძოლა · Tab — რაზმი · Q/E, ბორბალი — კამერა · H — დგომა",
"Commander":"მეთაური",
