"Top view of your squad: click orders, abilities 1–4.":"ხედი შენს რაზმზე ზემოდან: ბრძანებები დაწკაპუნებით, უნარები 1–4.",
"The third mode: top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"მესამე რეჟიმი: ხედი ერთ რაზმზე ზემოდან, ბრძანებები დაწკაპუნებით, 4 უნარი, რაზმის შეცვლა, მსროლელში ჩაყვინთვა და უკან დაბრუნება",
