"Point {0} taken, but there is no HQ — no pod will come":"წერტილი {0} აღებულია, მაგრამ შტაბი არ გაქვს — კაფსულა ვერ მოფრინდება",
"The bomber took off from the base — into the sky, it will come out over the target":"ბომბდამშენი ბაზიდან აფრინდა — ცაში გადის, სამიზნის თავზე გამოვა",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"აირჩიე ერთეული → „▶ ბრძოლაში\" ან ორმაგი შეხება. რეჟიმის ღილაკი მარჯვნივ ზემოთ: სტრატეგი → მეთაური → მსროლელი.",
