"Living world: requests, hero quests, breakthrough ops":"ცოცხალი სამყარო: თანამებრძოლთა თხოვნები, გმირთა კვესტები, ბრძოლის გარდატეხა",
"Living world":"ცოცხალი სამყარო",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"შენები დახმარებას გთხოვენ და გასაჩუქრებენ, გმირები კვესტებს გაძლევენ, გაჭიანურებულ ფრონტს ოპერაციით არღვევენ",
"A request":"თანამებრძოლთა თხოვნა",
"Breakthrough":"გარდატეხა",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"შენები ხანდახან დახმარებას გთხოვენ: ხმა რადიოთი, ბარათი „თხოვნა\" და მარკერი ✋. რაზმს ჩაუჭირეს — გაანადგურე მის გვერდით მყოფი მტრები. ჯილდო: ჯარისკაცი კაფსულით ბაზიდან, ქვემეხი ბაგის საბარგულიდან, მსროლელის ადგილი ან ორბიტალური დაფარვა. არ გინდა — ✕ ან უბრალოდ უგულებელყავი.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"ვეტერანი მზვერავი „ბუ\" კვესტს გთავაზობს. Y — მიღება (N — უარი). წადი ★ მარკერთან, გაანადგურე დაცვა და 3 წმ დადექი პილოტთან — ის შენს რაზმში ჩადგება.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"ფრონტი გაჩერდა — შტაბი გარდატეხას გთავაზობს. Y — მიღება. 8 წმ დაიკავე რელე მტრების გარეშე: მტრის რუკა 60 წმ ჩანს. გენერატორი — მტრის კოშკურები 2 წთ დუმს. სტრატეგში — „რაზმისთვის მიცემა\". მტერსაც შეუძლია ეს: ადევნე თვალი ⚠-ს.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"შენები დახმარებას გთხოვენ: ბარათი „თხოვნა\" და მარკერი ✋. გაანადგურე ჩაჭერილი რაზმის გვერდით მყოფი მტრები — ჯილდოს მიიღებ. ✕ — გამოტოვება.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"გმირი „ბუ\" კვესტს გთავაზობს — შეეხე „მიღებას\". წადი ★-თან, გაანადგურე დაცვა, დადექი პილოტთან.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"ფრონტი გაჩერდა — შეეხე „მიღებას\" და 8 წმ დაიკავე რელე: მტრის რუკა ერთი წუთით გაიხსნება.",
